/**
 * @method
 * @name txa_chrgMemoContn_onkeyup
 * @description txa_chrgMemoContn 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.txa_chrgMemoContn_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.setLength(selfVar.value, 'memoCharNum', '2000');

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil11080.txa_chrgMemoContn_onkeyup' }); }
};

/**
 * @method
 * @name txa_chrgMemoContn_onblur
 * @description txa_chrgMemoContn 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txa_chrgMemoContn_onblur = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.estimateCounter(selfVar, '2000');

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil11080.txa_chrgMemoContn_onblur' }); }
};

/**
 * @method
 * @name btn_list_onclick
 * @description 「목록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
