///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name attachFileList_fmt_attachFileNm
 * @description attach File List fmt attach File Nm 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.attachFileList_fmt_attachFileNm = function (data, formattedData, rowIndex, columnIndex) { return '<a href="javascript:void(0)"><strong>' + String(data) + '</strong></a>'; };

/**
 * @method
 * @name list
 * @description list 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list = async function () {
    $c.util.getComponent('ipt_method').setValue("disclsConsultCompltList");
    $("form[name='disclsConsultForm']").attr("onsubmit", "");
    const nr = await scwin.tx_fn_list();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil11070/jldfil11070.xml", { "method": "disclsConsultCompltList" });
    }
};

/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {String} ipt_disclsConsultApplId ipt_disclsConsultApplId
 * @param {*} seq seq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDown = async function (ipt_disclsConsultApplId, seq) {
    const isDisclsConsultServiced = $c.util.getComponent('ipt_isDisclsConsultServiced').getValue();
    if (isDisclsConsultServiced === 'Y') {
        const oData = await scwin.getOtherData();
        if (oData === '' || oData == null || oData === 'undefined') {
            void('apiKey 조회에 실패');
            return;
        }
        const arr = oData.split('||');
        const apiUrl = scwin.urlInfo();
        $c.util.getComponent('hideFrame').src = apiUrl + '/auth/s1/disclosure/consult-apply/file-download/' + ipt_disclsConsultApplId + '/' + seq + '?apiKey=' + arr[0] + '&integUsrId=' + arr[1];
        $c.util.getComponent('hideApiHist').src = 'disclsConsult.do?method=downloadHistUpdate&disclsConsultApplId=' + ipt_disclsConsultApplId + '&seq=' + seq;
    } else {
        $c.util.getComponent('hideFrame').src = 'disclsConsult.do?method=disclsConsultFileDown&disclsConsultApplId=' + ipt_disclsConsultApplId + '&seq=' + seq;
    }
};

/**
 * @method
 * @name fileAllDown
 * @description file All Down 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileAllDown = async function () {
    const chk = $('input:checkbox[name="attachDelChk"]');
    const seqArr = [];
    if (chk.length === 0) {
        return;
    } else {
        chk.each(function() {
                seqArr.push($(this).val());
        });
    }
    const isDisclsConsultServiced = $c.util.getComponent('ipt_isDisclsConsultServiced').getValue();
    if (isDisclsConsultServiced === 'Y') {
        const oData = await scwin.getOtherData();
        if (oData === '' || oData == null || oData === 'undefined') {
            void('apiKey 조회에 실패');
            return;
        }
        const arr = oData.split('||');
        const apiUrl = scwin.urlInfo();
        let j = 0;
        let it = setInterval(function() {
                if (j < chk.length) {
                    const frame = $('<iframe name="hideTotFrame' + j + '" id="hideTotFrame' + j + '" style="display:none;"></iframe>');
                    frame.appendTo('body');
                    $c.util.getComponent('hideTotFrame' + j).src = apiUrl + '/auth/s1/disclosure/consult-apply/file-download/' + $c.util.getComponent('ipt_disclsConsultApplId').getValue() + '/' + seqArr[j] + '?apiKey=' + arr[0] + '&integUsrId=' + arr[1];
                    $c.util.getComponent('hideApiHist').src = 'disclsConsult.do?method=downloadHistUpdate&disclsConsultApplId=' + $c.util.getComponent('ipt_disclsConsultApplId').getValue() + '&seq=' + seqArr[j];
                    j++;
                } else {
                    clearInterval(it);
                }
            }, 500);
    } else {
        j = 0;
        it = setInterval(function() {
                if (j < chk.length) {
                    const frame = $('<iframe name="hideTotFrame' + j + '" id="hideTotFrame' + j + '" style="display:none;"></iframe>');
                    frame.appendTo('body');
                    $c.util.getComponent('hideTotFrame' + j).src = 'disclsConsult.do?method=disclsConsultFileDown&disclsConsultApplId=' + $c.util.getComponent('ipt_disclsConsultApplId').getValue() + '&seq=' + seqArr[j];
                    j++;
                } else {
                    clearInterval(it);
                }
            }, 500);
    }
};

/**
 * @method
 * @name urlInfo
 * @description url Info 처리
 * @returns {void}
 * @hidden N
 */
scwin.urlInfo = function () {
    let returnUrl = '';
    const url = location.host;
    if (url === ('localhost:8081') || url === ('idev-filing.krx.co.kr')) {
        returnUrl = 'https://idev-kind-api.krx.co.kr';
    } else {
        if (url === ('dev-filing.krx.co.kr')) {
            returnUrl = 'https://dev-kind-api.krx.co.kr';
        } else {
            if (url === ('test-filing.krx.co.kr')) {
                returnUrl = 'https://test-kind-api.krx.co.kr';
            } else {
                if (url === ('filing.krx.co.kr')) {
                    returnUrl = 'https://kind-api.krx.co.kr';
                } else {
                    if (url === ('dr-filing.krx.co.kr')) {
                        returnUrl = 'https://dr-kind-api.krx.co.kr';
                    }
                }
            }
        }
    }
    return returnUrl;
};

/**
 * @method
 * @name setLength
 * @description set Length 처리
 * @param {Object} obj 컴포넌트
 * @param {*} tdName tdName
 * @param {*} maxLength maxLength
 * @returns {void}
 * @hidden N
 */
scwin.setLength = function (obj, tdName, maxLength) {
    const strLength = scwin.calBytes(obj);
    ($c.util.getComponent(tdName) && $c.util.getComponent(tdName).setValue) ? $c.util.getComponent(tdName).setValue("(" + strLength + "/" + maxLength + ")") : (($c.util.getComponent(tdName) && $c.util.getComponent(tdName).setText) ? $c.util.getComponent(tdName).setText("(" + strLength + "/" + maxLength + ")") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + tdName), void ("(" + strLength + "/" + maxLength + ")")));
};

/**
 * @method
 * @name estimateCounter
 * @description estimate Counter 처리
 * @param {Object} obj 컴포넌트
 * @param {*} maxLength maxLength
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.estimateCounter = async function (obj, maxLength) {
    if (scwin.calBytes(obj.value) > maxLength) {
        await $c.win.alert('한글 1000자 이하, 숫자/영문 2000자 이하까지만 입력이 가능합니다.');
        obj.select();
        return;
    }
};

/**
 * @method
 * @name calBytes
 * @description cal Bytes 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.calBytes = function (str) {
    let tcount = 0;
    const tmpStr = new String(str);
    const temp = tmpStr.length;
    let onechar;
    for (let k = 0; k < temp; k++) {
        onechar = tmpStr.charAt(k);
        if (escape(onechar).length > 4) {
            tcount += 2;
        } else {
            if (escape(onechar) === '%0A') {
                tcount += 2;
            } else {
                tcount += 1;
            }
        }
    }
    return tcount;
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    $c.util.getComponent('ipt_method').setValue("disclsConsultCompltUpdate");
    $("form[name='disclsConsultForm']").attr("onsubmit", "");
    await scwin.tx_fn_register();
};

/**
 * @method
 * @name fileDel
 * @description file Del 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDel = async function () {
    let chkCnt = 0;
    $('input:checkbox[name="attachDelChk"]').each(function() {
            if (this.checked) {
                chkCnt++;
            }
    });
    if (chkCnt === 0) {
        await $c.win.alert('삭제할 파일을 체크해주세요.');
        return;
    } else {
        await $c.win.openPopup('/jldfil11080/jldfil11080_layer_layer1.xml', {id:'jldfil11080_layer_layer1', type:'pageFramePopup'}, {});
    }
};

/**
 * @method
 * @name layer_popup
 * @description layer popup 처리
 * @param {*} el el
 * @returns {void}
 * @hidden N
 */
scwin.layer_popup = function (el) {
    const $el = $(el);
    const isDim = $el.prev().hasClass('dimBg');
    isDim ? $('.dim-layer').fadeIn() : $el.fadeIn();
    let $elWidth = ~~($el.outerWidth()), $elHeight = ~~($el.outerHeight()), docWidth = $(document).width(), docHeight = $(document).height();
    if ($elHeight < docHeight || $elWidth < docWidth) {
        $elHeight = 500;
        $el.css({ marginTop: -$elHeight / 2, marginLeft: -$elWidth / 2 });
    } else {
        $el.css({ top: 0, left: 0 });
    }
    $el.find('#btnClose').click(function() {
            ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('txa_delRsn', '') : console.warn('[sdd] hiddenStore 부재: txa_delRsn'));
            isDim ? $('.dim-layer').fadeOut() : $el.fadeOut();
            return false;
    });
    $('.layer .dimBg').click(function() {
            $('.dim-layer').fadeOut();
            return false;
    });
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name getAttachFileListDone
 * @description get Attach File List Done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.getAttachFileListDone = function (data) {
    scwin.result = (typeof data === "string" ? JSON.parse(data) : data); $c.util.getComponent('dlt_attachFileList').setJSON(scwin.result);
    if (scwin.result.length > 0) {
        /* 컨테이너 비움 → setJSON 전체 교체가 대신(D14-A) */
        const dCnt = 1;
        /* 컨테이너 조립 루프 → 그리드 공급으로 대체(D14-A): 행은 dlt_attachFileList 가 싣고 열 동작은 그리드 라우터가 낸다 */
        $c.util.getComponent('attachFileList').setStyle("display", "");
        $c.util.getComponent('attachDel').setStyle("display", "");
    } else {
        $c.util.getComponent('attachFileList').setStyle("display", "none");
        $c.util.getComponent('attachDel').setStyle("display", "none");
    }
};

/**
 * @method
 * @name getAttachFileList
 * @description get Attach File List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getAttachFileList = async function () {
    const r = await scwin.tx_fn_getAttachFileList();
    try {
        scwin.getAttachFileListDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldfil11080.fn_getAttachFileList' });
    }
    return r;
};

/**
